        else:
            s = "datetime.datetime(%d, %d, %d, %d, %d" % (self.year, self.month, self.day, self.hour, self.minute)
        if self.tzinfo is not None:
            s += ", tzinfo=%r" % (self.tzinfo,)
        return s + ")"


