def _num(s, i, lo, hi):
    j = i
    n = len(s)
    while j < n and j - i < hi and s[j].isdigit():
        j += 1
    if j - i < lo:
        raise ValueError("bad number")
    return int(s[i:j]), j


def _strptime(cls, s, fmt):
    y = 1900
    mo = 1
    d = 1
    hh = 0
    mi = 0
    ss = 0
    us = 0
    pm = None
    yday = None
    tz = None
    i = 0
    j = 0
    n = len(fmt)
    sl = len(s)
    try:
        while j < n:
            c = fmt[j]
            j += 1
            if c != "%":
                if c in " \t\n":
                    while i < sl and s[i] in " \t\n":
                        i += 1
                else:
                    if i >= sl or s[i] != c:
                        raise ValueError("mismatch")
                    i += 1
                continue
            c = fmt[j]
            j += 1
            if c == "-" and j < n:
                c = fmt[j]
                j += 1
            if c == "Y":
                y, i = _num(s, i, 4, 4)
            elif c == "y":
                y, i = _num(s, i, 2, 2)
                y += 2000 if y < 69 else 1900
            elif c == "m":
                mo, i = _num(s, i, 1, 2)
            elif c == "d" or c == "e":
                while c == "e" and i < sl and s[i] == " ":
                    i += 1
                d, i = _num(s, i, 1, 2)
            elif c == "H":
                hh, i = _num(s, i, 1, 2)
            elif c == "I":
                hh, i = _num(s, i, 1, 2)
            elif c == "M":
                mi, i = _num(s, i, 1, 2)
            elif c == "S":
                ss, i = _num(s, i, 1, 2)
            elif c == "f":
                k = i
                while k < sl and k - i < 6 and s[k].isdigit():
                    k += 1
                if k == i:
                    raise ValueError("bad")
                us = int((s[i:k] + "000000")[:6])
                i = k
            elif c == "j":
                yday, i = _num(s, i, 1, 3)
            elif c == "p":
                t = s[i:i + 2].upper()
                if t == "AM":
                    pm = False
                elif t == "PM":
                    pm = True
                else:
                    raise ValueError("bad")
                i += 2
            elif c == "B" or c == "b" or c == "h":
                found = False
                for k in range(1, 13):
                    for nm in (_MONTHS[k], _MONTHS[k][:3]):
                        if s[i:i + len(nm)].lower() == nm.lower():
                            if not found or len(nm) > 3:
                                mo = k
                                ln = len(nm)
                                found = True
                    if found:
                        break
                if not found:
                    raise ValueError("bad month")
                i += ln
            elif c == "A" or c == "a":
                found = False
                for k in range(7):
                    for nm in (_DAYS[k], _DAYS[k][:3]):
                        if s[i:i + len(nm)].lower() == nm.lower() and (not found or len(nm) > 3):
                            ln = len(nm)
                            found = True
                    if found:
                        break
                if not found:
                    raise ValueError("bad weekday")
                i += ln
            elif c == "z":
                k = i
                if k < sl and s[k] in "Zz":
                    tz = timezone.utc
                    i = k + 1
                else:
                    sign = 1
                    if s[k] == "-":
                        sign = -1
                    elif s[k] != "+":
                        raise ValueError("bad tz")
                    k += 1
                    h2, k = _num(s, k, 2, 2)
                    if k < sl and s[k] == ":":
                        k += 1
                    m2, k = _num(s, k, 2, 2)
                    tz = timezone(timedelta(seconds=sign * (h2 * 3600 + m2 * 60)))
                    i = k
            elif c == "Z":
                k = i
                while k < sl and s[k].isalpha():
                    k += 1
                i = k
            elif c == "%":
                if i >= sl or s[i] != "%":
                    raise ValueError("mismatch")
                i += 1
            else:
                raise ValueError("'%s' is a bad directive in format '%s'" % (c, fmt))
        if i != sl:
            raise ValueError("unconverted data remains: " + s[i:])
    except (ValueError, IndexError):
        raise ValueError("time data %r does not match format %r" % (s, fmt))
    if pm is not None:
        if pm and hh < 12:
            hh += 12
        elif not pm and hh == 12:
            hh = 0
    if yday is not None:
        dd = date.fromordinal(_ymd2ord(y, 1, 1) + yday - 1)
        mo = dd.month
        d = dd.day
    return cls(y, mo, d, hh, mi, ss, us, tz)

