"""heapq: heap queue algorithm (same sift algorithms as CPython, so heap layouts agree)."""


def _siftdown(heap, startpos, pos):
    newitem = heap[pos]
    while pos > startpos:
        parentpos = (pos - 1) >> 1
        parent = heap[parentpos]
        if newitem < parent:
            heap[pos] = parent
            pos = parentpos
            continue
        break
    heap[pos] = newitem


def _siftup(heap, pos):
    endpos = len(heap)
    startpos = pos
    newitem = heap[pos]
    childpos = 2 * pos + 1
    while childpos < endpos:
        rightpos = childpos + 1
        if rightpos < endpos and not heap[childpos] < heap[rightpos]:
            childpos = rightpos
        heap[pos] = heap[childpos]
        pos = childpos
        childpos = 2 * pos + 1
    heap[pos] = newitem
    _siftdown(heap, startpos, pos)


def heappush(heap, item):
    heap.append(item)
    _siftdown(heap, 0, len(heap) - 1)


def heappop(heap):
    if not heap:
        raise IndexError("index out of range")
    lastelt = heap.pop()
    if heap:
        returnitem = heap[0]
        heap[0] = lastelt
        _siftup(heap, 0)
        return returnitem
    return lastelt


def heapreplace(heap, item):
    if not heap:
        raise IndexError("index out of range")
    returnitem = heap[0]
    heap[0] = item
    _siftup(heap, 0)
    return returnitem


def heappushpop(heap, item):
    if heap and heap[0] < item:
        item, heap[0] = heap[0], item
        _siftup(heap, 0)
    return item


def heapify(x):
    n = len(x)
    for i in range(n // 2 - 1, -1, -1):
        _siftup(x, i)


def nlargest(n, iterable, key=None):
    return sorted(iterable, key=key, reverse=True)[:n]


def nsmallest(n, iterable, key=None):
    return sorted(iterable, key=key)[:n]


class _Merge:
    # not a generator function: generators of imported modules cannot see module globals on one interpreter
    def __init__(self, iterables, key, reverse):
        self.key = key
        self.reverse = reverse
        self.h = []
        order = 0
        for it in iterables:
            it = iter(it)
            for v in it:
                k = v if key is None else key(v)
                self.h.append([k, order, v, it])
                order += 1
                break
        if not reverse:
            heapify(self.h)

    def __iter__(self):
        return self

    def __next__(self):
        h = self.h
        if not h:
            raise StopIteration
        if self.reverse:
            bi = 0
            for i in range(1, len(h)):
                if h[i][0] > h[bi][0]:
                    bi = i
        else:
            bi = 0
        e = h[bi]
        res = e[2]
        nxt = False
        key = self.key
        for v in e[3]:
            e[0] = v if key is None else key(v)
            e[2] = v
            nxt = True
            break
        if self.reverse:
            if not nxt:
                del h[bi]
        elif nxt:
            _siftup(h, 0)
        else:
            heappop(h)
        return res


def merge(*iterables, key=None, reverse=False):
    return _Merge(iterables, key, reverse)


_heappop_max = None

io.py:
"""io: a small pure-Python StringIO (text only) -- runs on any interpreter of this project."""


class StringIO:
    def __init__(self, initial_value="", newline="\n"):
        self._buf = initial_value
        self._pos = 0
        self.closed = False

    def _check(self):
        if self.closed:
            raise ValueError("I/O operation on closed file.")

    def write(self, s):
        self._check()
        if not isinstance(s, str):
            raise TypeError("string argument expected, got '%s'" % type(s).__name__)
        n = len(s)
        if self._pos == len(self._buf):
            self._buf = self._buf + s
        else:
            if self._pos > len(self._buf):
                self._buf = self._buf + "\0" * (self._pos - len(self._buf))
            self._buf = self._buf[:self._pos] + s + self._buf[self._pos + n:]
        self._pos += n
        return n

    def writelines(self, lines):
        for line in lines:
            self.write(line)

    def getvalue(self):
        self._check()
        return self._buf

    def read(self, size=-1):
        self._check()
        if size is None or size < 0:
            r = self._buf[self._pos:]
        else:
            r = self._buf[self._pos:self._pos + size]
        self._pos += len(r)
        return r

    def readline(self, size=-1):
        self._check()
        if self._pos >= len(self._buf):
            return ""
        i = self._buf.find("\n", self._pos)
        end = len(self._buf) if i < 0 else i + 1
        if size is not None and size >= 0 and self._pos + size < end:
            end = self._pos + size
        r = self._buf[self._pos:end]
        self._pos = end
        return r

    def readlines(self, hint=-1):
        out = []
        while True:
            line = self.readline()
            if line == "":
                break
            out.append(line)
        return out

    def __iter__(self):
        return self

    def __next__(self):
        line = self.readline()
        if line == "":
            raise StopIteration
        return line

    def seek(self, pos, whence=0):
        self._check()
        if whence == 0:
            self._pos = pos
        elif whence == 1:
            self._pos = self._pos + pos
        else:
            self._pos = len(self._buf) + pos
        return self._pos

    def tell(self):
        self._check()
        return self._pos

    def truncate(self, size=None):
        self._check()
        if size is None:
            size = self._pos
        self._buf = self._buf[:size]
        return size

    def close(self):
        self.closed = True

    def readable(self):
        return True

    def writable(self):
        return True

    def seekable(self):
        return True

    def isatty(self):
        return False

    def flush(self):
        pass

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()
        return False

itertools.py:
"""itertools in pure Python (generators)."""


def chain(*iterables):
    for it in iterables:
        for x in it:
            yield x


def _from_iterable(iterables):
    for it in iterables:
        for x in it:
            yield x


chain.from_iterable = _from_iterable


def islice(iterable, *args):
    n = len(args)
    if n == 1:
        start = 0
        stop = args[0]
        step = 1
    else:
        start = args[0]
        stop = args[1]
        step = 1
        if n > 2:
            step = args[2]
        if start is None:
            start = 0
        if step is None:
            step = 1
    if start < 0 or (stop is not None and stop < 0) or step <= 0:
        raise ValueError("Indices for islice() must be None or an integer: 0 <= x <= sys.maxsize.")
    it = iter(iterable)
    i = 0
    nxt = start
    if stop is not None and nxt >= stop:
        return
    for x in it:
        if i == nxt:
            yield x
            nxt += step
            if stop is not None and nxt >= stop:
                return
        i += 1


def count(start=0, step=1):
    n = start
    while True:
        yield n
        n += step


def cycle(iterable):
    saved = []
    for x in iterable:
        yield x
        saved.append(x)
    if not saved:
        return
    while True:
        for x in saved:
            yield x


def repeat(obj, times=None):
    if times is None:
        while True:
            yield obj
    else:
        for _ in range(times):
            yield obj


def accumulate(iterable, func=None, initial=None):
    it = iter(iterable)
    total = initial
    if initial is None:
        try:
            total = next(it)
        except StopIteration:
            return
    yield total
    if func is None:
        for x in it:
            total = total + x
            yield total
    else:
        for x in it:
            total = func(total, x)
            yield total


def groupby(iterable, key=None):
    it = iter(iterable)
    try:
        v = next(it)
    except StopIteration:
        return
    k = v if key is None else key(v)
    while True:
        grp = [v]
        done = True
        for v in it:
            k2 = v if key is None else key(v)
            if k2 == k:
                grp.append(v)
            else:
                done = False
                break
        yield (k, iter(grp))
        if done:
            return
        k = k2


def zip_longest(*iterables, fillvalue=None):
    its = [iter(x) for x in iterables]
    n = len(its)
    if n == 0:
        return
    alive = n
    while True:
        row = []
        for i in range(n):
            it = its[i]
            if it is None:
                row.append(fillvalue)
            else:
                try:
                    row.append(next(it))
                except StopIteration:
                    alive -= 1
                    its[i] = None
                    row.append(fillvalue)
        if alive == 0:
            return
        yield tuple(row)


def starmap(function, iterable):
    for args in iterable:
        yield function(*args)


def takewhile(predicate, iterable):
    for x in iterable:
        if predicate(x):
            yield x
        else:
            return


def dropwhile(predicate, iterable):
    it = iter(iterable)
    for x in it:
        if not predicate(x):
            yield x
            break
    for x in it:
        yield x


def filterfalse(predicate, iterable):
    for x in iterable:
        if predicate is None:
            if not x:
                yield x
        elif not predicate(x):
            yield x


def compress(data, selectors):
    for d, s in zip(data, selectors):
        if s:
            yield d


def pairwise(iterable):
    it = iter(iterable)
    try:
        a = next(it)
    except StopIteration:
        return
    for b in it:
        yield (a, b)
        a = b


def batched(iterable, n, strict=False):
    if n < 1:
        raise ValueError("n must be at least one")
    it = iter(iterable)
    while True:
        b = []
        for x in it:
            b.append(x)
            if len(b) == n:
                break
        if not b:
            return
        if strict and len(b) < n:
            raise ValueError("batched(): incomplete batch")
        yield tuple(b)
        if len(b) < n:
            return


class _TeeData:
    def __init__(self, it):
        self.it = it
        self.buf = []
        self.base = 0


def _tee_iter(data, pos):
    while True:
        i = pos - data.base
        if i >= len(data.buf):
            try:
                x = next(data.it)
            except StopIteration:
                return
            data.buf.append(x)
        else:
            x = data.buf[i]
        pos += 1
        yield x


def tee(iterable, n=2):
    data = _TeeData(iter(iterable))
    return tuple([_tee_iter(data, 0) for _ in range(n)])


def product(*iterables, repeat=1):
    pools = [tuple(p) for p in iterables] * repeat
    n = len(pools)
    for p in pools:
        if not p:
            return
    idx = [0] * n
    yield tuple([p[0] for p in pools])
    if n == 0:
        return
    while True:
        i = n - 1
        while i >= 0:
            idx[i] += 1
            if idx[i] < len(pools[i]):
                break
            idx[i] = 0
            i -= 1
        if i < 0:
            return
        yield tuple([pools[j][idx[j]] for j in range(n)])


def permutations(iterable, r=None):
    pool = tuple(iterable)
    n = len(pool)
    if r is None:
        r = n
    if r > n or r < 0:
        return
    indices = list(range(n))
    cycles = list(range(n, n - r, -1))
    yield tuple([pool[i] for i in indices[:r]])
    while n:
        i = r - 1
        while i >= 0:
            cycles[i] -= 1
            if cycles[i] == 0:
                indices[i:] = indices[i + 1:] + indices[i:i + 1]
                cycles[i] = n - i
                i -= 1
            else:
                j = cycles[i]
                indices[i], indices[-j] = indices[-j], indices[i]
                yield tuple([pool[k] for k in indices[:r]])
                break
        if i < 0:
            return


def combinations(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r > n or r < 0:
        return
    indices = list(range(r))
    yield tuple([pool[i] for i in indices])
    while True:
        i = r - 1
        while i >= 0 and indices[i] == i + n - r:
            i -= 1
        if i < 0:
            return
        indices[i] += 1
        for j in range(i + 1, r):
            indices[j] = indices[j - 1] + 1
        yield tuple([pool[k] for k in indices])


def combinations_with_replacement(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if not n and r:
        return
    indices = [0] * r
    yield tuple([pool[i] for i in indices])
    while True:
        i = r - 1
        while i >= 0 and indices[i] == n - 1:
            i -= 1
        if i < 0:
            return
        v = indices[i] + 1
        for j in range(i, r):
            indices[j] = v
        yield tuple([pool[k] for k in indices])

json.py:
"""json: dumps/dump/loads/load in pure Python."""

# strings are bytes (UTF-8) in one interpreter and code points in the other
_BYTES = len(chr(233)) != 1
_HEX = "0123456789abcdef"
_CTLS = [chr(i) for i in range(32) if i not in (8, 9, 10, 12, 13)]


_chr = chr


class JSONDecodeError(ValueError):
    def __init__(self, msg, doc, pos):
        lineno = doc.count("\n", 0, pos) + 1
        colno = pos - doc.rfind("\n", 0, pos)
        ValueError.__init__(self, "%s: line %d column %d (char %d)" % (msg, lineno, colno, pos))
        self.msg = msg
        self.doc = doc
        self.pos = pos
        self.lineno = lineno
        self.colno = colno


def _u4(n):
    return "\\u" + _HEX[(n >> 12) & 15] + _HEX[(n >> 8) & 15] + _HEX[(n >> 4) & 15] + _HEX[n & 15]


def _escape_slow(s, ascii_only):
    out = []
    n = len(s)
    i = 0
    while i < n:
        c = s[i]
        o = ord(c)
        i += 1
        if o < 128:
            if o < 32:
                out.append(_u4(o))
            else:
                out.append(c)
            continue
        if not ascii_only:
            out.append(c)
            continue
        if _BYTES:
            # decode one UTF-8 sequence from byte values
            if o >= 240 and i + 2 < n:
                cp = ((o & 7) << 18) | ((ord(s[i]) & 63) << 12) | ((ord(s[i + 1]) & 63) << 6) | (ord(s[i + 2]) & 63)
                i += 3
            elif o >= 224 and i + 1 < n:
                cp = ((o & 15) << 12) | ((ord(s[i]) & 63) << 6) | (ord(s[i + 1]) & 63)
                i += 2
            elif o >= 192 and i < n:
                cp = ((o & 31) << 6) | (ord(s[i]) & 63)
                i += 1
            else:
                cp = o
        else:
            cp = o
        if cp >= 65536:
            cp -= 65536
            out.append(_u4(55296 | (cp >> 10)))
            out.append(_u4(56320 | (cp & 1023)))
        else:
            out.append(_u4(cp))
    return "".join(out)


def _quote(s, ascii_only=True):
    if s.isalnum() and s.isascii():
        return '"' + s + '"'
    if s.isascii():
        s = s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r")
        s = s.replace("\t", "\\t").replace("\x08", "\\b").replace("\x0c", "\\f")
        for c in _CTLS:
            if c in s:
                return '"' + _escape_slow(s, ascii_only) + '"'
        return '"' + s + '"'
    s = s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r")
    s = s.replace("\t", "\\t").replace("\x08", "\\b").replace("\x0c", "\\f")
    return '"' + _escape_slow(s, ascii_only) + '"'


def _float_repr(f, allow_nan):
    if f != f:
        t = "NaN"
    elif f == float("inf"):
        t = "Infinity"
    elif f == float("-inf"):
        t = "-Infinity"
    else:
        return repr(f)
    if not allow_nan:
        raise ValueError("Out of range float values are not JSON compliant: " + repr(f))
    return t


class JSONEncoder:
    def __init__(self, skipkeys=False, ensure_ascii=True, check_circular=True, allow_nan=True,
                 sort_keys=False, indent=None, separators=None, default=None):
        self.skipkeys = skipkeys
        self.ensure_ascii = ensure_ascii
        self.allow_nan = allow_nan
        self.sort_keys = sort_keys
        if isinstance(indent, int) and not isinstance(indent, bool):
            indent = " " * indent
        self.indent = indent
        if separators is not None:
            self.item_separator = separators[0]
            self.key_separator = separators[1]
        elif indent is not None:
            self.item_separator = ","
            self.key_separator = ": "
        else:
            self.item_separator = ", "
            self.key_separator = ": "
        if default is not None:
            self.default = default

    def default(self, o):
        raise TypeError("Object of type %s is not JSON serializable" % type(o).__name__)

    def encode(self, o):
        out = []
        self._enc(o, out, 0)
        return "".join(out)

    def iterencode(self, o):
        return iter([self.encode(o)])

    def _key(self, k):
        if isinstance(k, str):
            return k
        if k is True:
            return "true"
        if k is False:
            return "false"
        if k is None:
            return "null"
        if isinstance(k, int):
            return str(k)
        if isinstance(k, float):
            return _float_repr(k, self.allow_nan)
        return None

    def _enc(self, o, out, level):
        if isinstance(o, str):
            out.append(_quote(o, self.ensure_ascii))
        elif o is None:
            out.append("null")
        elif o is True:
            out.append("true")
        elif o is False:
            out.append("false")
        elif isinstance(o, int):
            out.append(str(o))
        elif isinstance(o, float):
            out.append(_float_repr(o, self.allow_nan))
        elif isinstance(o, (list, tuple)):
            if not o:
                out.append("[]")
                return
            ind = self.indent
            if ind is None:
                sep = self.item_separator
                nl = ""
            else:
                nl = "\n" + ind * (level + 1)
                sep = self.item_separator + nl
                out.append("[" + nl)
            if ind is None:
                out.append("[")
            first = True
            for v in o:
                if not first:
                    out.append(sep)
                first = False
                self._enc(v, out, level + 1)
            if ind is None:
                out.append("]")
            else:
                out.append("\n" + ind * level + "]")
        elif isinstance(o, dict):
            if not o:
                out.append("{}")
                return
            ind = self.indent
            if ind is None:
                sep = self.item_separator
                out.append("{")
            else:
                nl = "\n" + ind * (level + 1)
                sep = self.item_separator + nl
                out.append("{" + nl)
            items = list(o.items())
            if self.sort_keys:
                items = sorted(items, key=lambda kv: kv[0])
            first = True
            for k, v in items:
                ks = self._key(k)
                if ks is None:
                    if self.skipkeys:
                        continue
                    raise TypeError("keys must be str, int, float, bool or None, not %s" % type(k).__name__)
                if not first:
                    out.append(sep)
                first = False
                out.append(_quote(ks, self.ensure_ascii))
                out.append(self.key_separator)
                self._enc(v, out, level + 1)
            if ind is None:
                out.append("}")
            else:
                out.append("\n" + ind * level + "}")
        else:
            self._enc(self.default(o), out, level)


def dumps(obj, skipkeys=False, ensure_ascii=True, check_circular=True, allow_nan=True, cls=None,
          indent=None, separators=None, default=None, sort_keys=False, **kw):
    if cls is None:
        cls = JSONEncoder
    return cls(skipkeys=skipkeys, ensure_ascii=ensure_ascii, allow_nan=allow_nan, indent=indent,
               separators=separators, default=default, sort_keys=sort_keys).encode(obj)


def dump(obj, fp, **kw):
    fp.write(dumps(obj, **kw))


_WS = " \t\n\r"
_NUMCH = "0123456789+-.eE"
_ESC = {'"': '"', "\\": "\\", "/": "/", "b": "\x08", "f": "\x0c", "n": "\n", "r": "\r", "t": "\t"}


class JSONDecoder:
    def __init__(self, object_hook=None, parse_float=None, parse_int=None, parse_constant=None,
                 strict=True, object_pairs_hook=None):
        self.object_hook = object_hook
        self.object_pairs_hook = object_pairs_hook
        self.parse_float = parse_float
        self.parse_int = parse_int
        self.parse_constant = parse_constant
        self.s = ""
        self.n = 0

    def decode(self, s):
        self.s = s
        self.n = len(s)
        i = self._ws(0)
        v, i = self._value(i)
        i = self._ws(i)
        if i != self.n:
            raise JSONDecodeError("Extra data", s, i)
        return v

    def raw_decode(self, s, idx=0):
        self.s = s
        self.n = len(s)
        return self._value(self._ws(idx))

    def _ws(self, i):
        s = self.s
        n = self.n
        while i < n and s[i] in _WS:
            i += 1
        return i

    def _string(self, i):
        # i is just after the opening quote
        s = self.s
        j = s.find('"', i)
        if j < 0:
            raise JSONDecodeError("Unterminated string starting at", s, i - 1)
        chunk = s[i:j]
        if "\\" not in chunk:
            return chunk, j + 1
        out = []
        n = self.n
        while True:
            j = i
            while j < n and s[j] != '"' and s[j] != "\\":
                j += 1
            if j >= n:
                raise JSONDecodeError("Unterminated string starting at", s, i - 1)
            out.append(s[i:j])
            if s[j] == '"':
                return "".join(out), j + 1
            j += 1
            if j >= n:
                raise JSONDecodeError("Unterminated string starting at", s, i - 1)
            c = s[j]
            if c == "u":
                h = s[j + 1:j + 5]
                try:
                    cp = int(h, 16)
                except ValueError:
                    raise JSONDecodeError("Invalid \\uXXXX escape", s, j - 1)
                j += 5
                if 55296 <= cp < 56320 and s[j:j + 2] == "\\u":
                    try:
                        lo = int(s[j + 2:j + 6], 16)
                    except ValueError:
                        lo = 0
                    if 56320 <= lo < 57344:
                        cp = 65536 + (((cp - 55296) << 10) | (lo - 56320))
                        j += 6
                out.append(_chr(cp))
                i = j
            elif c in _ESC:
                out.append(_ESC[c])
                i = j + 1
            else:
                raise JSONDecodeError("Invalid \\escape", s, j - 1)

    def _value(self, i):
        s = self.s
        if i >= self.n:
            raise JSONDecodeError("Expecting value", s, i)
        c = s[i]
        if c == '"':
            return self._string(i + 1)
        if c == "{":
            return self._object(i + 1)
        if c == "[":
            return self._array(i + 1)
        if c == "t" and s[i:i + 4] == "true":
            return True, i + 4
        if c == "f" and s[i:i + 5] == "false":
            return False, i + 5
        if c == "n" and s[i:i + 4] == "null":
            return None, i + 4
        if c == "N" and s[i:i + 3] == "NaN":
            return float("nan"), i + 3
        if c == "I" and s[i:i + 8] == "Infinity":
            return float("inf"), i + 8
        if c == "-" and s[i:i + 9] == "-Infinity":
            return float("-inf"), i + 9
        j = i
        n = self.n
        isf = False
        while j < n and s[j] in _NUMCH:
            if s[j] in ".eE":
                isf = True
            j += 1
        if j == i:
            raise JSONDecodeError("Expecting value", s, i)
        t = s[i:j]
        try:
            if isf:
                if self.parse_float is not None:
                    return self.parse_float(t), j
                return float(t), j
            if self.parse_int is not None:
                return self.parse_int(t), j
            return int(t), j
        except ValueError:
            raise JSONDecodeError("Expecting value", s, i)

    def _array(self, i):
        s = self.s
        res = []
        i = self._ws(i)
        if i < self.n and s[i] == "]":
            return res, i + 1
        while True:
            v, i = self._value(i)
            res.append(v)
            i = self._ws(i)
            if i >= self.n:
                raise JSONDecodeError("Expecting ',' delimiter", s, i)
            c = s[i]
            if c == "]":
                return res, i + 1
            if c != ",":
                raise JSONDecodeError("Expecting ',' delimiter", s, i)
            i = self._ws(i + 1)

    def _object(self, i):
        s = self.s
        pairs = []
        i = self._ws(i)
        if i < self.n and s[i] == "}":
            i += 1
        else:
            while True:
                if i >= self.n or s[i] != '"':
                    raise JSONDecodeError("Expecting property name enclosed in double quotes", s, i)
                k, i = self._string(i + 1)
                i = self._ws(i)
                if i >= self.n or s[i] != ":":
                    raise JSONDecodeError("Expecting ':' delimiter", s, i)
                i = self._ws(i + 1)
                v, i = self._value(i)
                pairs.append((k, v))
                i = self._ws(i)
                if i >= self.n:
                    raise JSONDecodeError("Expecting ',' delimiter", s, i)
                c = s[i]
                if c == "}":
                    i += 1
                    break
                if c != ",":
                    raise JSONDecodeError("Expecting ',' delimiter", s, i)
                i = self._ws(i + 1)
        if self.object_pairs_hook is not None:
            return self.object_pairs_hook(pairs), i
        d = {}
        for k, v in pairs:
            d[k] = v
        if self.object_hook is not None:
            return self.object_hook(d), i
        return d, i


def loads(s, cls=None, object_hook=None, parse_float=None, parse_int=None, parse_constant=None,
          object_pairs_hook=None, **kw):
    if not isinstance(s, str):
        if hasattr(s, "decode"):
            s = s.decode()
        else:
            raise TypeError("the JSON object must be str, bytes or bytearray, not %s" % type(s).__name__)
    if cls is None:
        cls = JSONDecoder
    return cls(object_hook=object_hook, parse_float=parse_float, parse_int=parse_int,
               parse_constant=parse_constant, object_pairs_hook=object_pairs_hook).decode(s)


def load(fp, **kw):
    return loads(fp.read(), **kw)

