        return np.array([cross(np.array(p), np.array(q)).tolist() for p, q in zip(ra, rb)])
    p = a.tolist()
    q = b.tolist()
    if len(p) == 2 and len(q) == 2:
        return p[0] * q[1] - p[1] * q[0]
    return np.array([p[1] * q[2] - p[2] * q[1], p[2] * q[0] - p[0] * q[2], p[0] * q[1] - p[1] * q[0]])


