def searchsorted(a, v, side='left'):
    lst = _arr(a).tolist()

    def one(x):
        lo = 0
        hi = len(lst)
        while lo < hi:
            mid = (lo + hi) // 2
            if (lst[mid] < x) if side == 'left' else (lst[mid] <= x):
                lo = mid + 1
            else:
                hi = mid
        return lo
    if isinstance(v, (int, float)):
        return one(v)
    vv = _arr(v)
    if vv.ndim == 0:
        return one(vv.tolist())
    return np.array([one(x) for x in vv.flatten().tolist()]).reshape(vv.shape)


