def bincount(x, weights=None, minlength=0):
    xs = _arr(x).tolist()
    n = max(max(xs) + 1 if xs else 0, minlength)
    out = [0] * n
    if weights is None:
        for v in xs:
            out[v] += 1
        return np.array(out)
    out = [0.0] * n
    for v, w in zip(xs, _arr(weights).tolist()):
        out[v] += w
    return np.array(out)


def interp(x, xp, fp):
    xs = _arr(xp).tolist()
    ys = _arr(fp).tolist()

    def one(v):
        if v <= xs[0]:
            return float(ys[0])
        if v >= xs[-1]:
            return float(ys[-1])
        lo = 0
        hi = len(xs) - 1
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if xs[mid] <= v:
                lo = mid
            else:
                hi = mid
        t = (v - xs[lo]) / (xs[hi] - xs[lo])
        return ys[lo] + t * (ys[hi] - ys[lo])
    if isinstance(x, (int, float)):
        return one(x)
    return _map(one, x)


