    return _map(one, x)


def polyfit(x, y, deg):
    from numpy import linalg as _la
    xs = _arr(x).flatten().tolist()
    A = np.array([[v ** (deg - j) for j in _range(deg + 1)] for v in xs], dtype=float)
    sol = _la.lstsq(A, _arr(y).astype(float), rcond=None)[0]
    return sol


