    n = max(len(a), len(b))
    a = [0] * (n - len(a)) + a
    b = [0] * (n - len(b)) + b
    return np.array([p + q for p, q in zip(a, b)])


def convolve(a, v, mode='full'):
    a = _arr(a).tolist()
    v = _arr(v).tolist()
    n = len(a)
    m = len(v)
    full = [0] * (n + m - 1)
    for i in _range(n):
        for j in _range(m):
            full[i + j] += a[i] * v[j]
    if mode == 'full':
        return np.array(full)
    if mode == 'same':
        lo = (m - 1) // 2
        return np.array(full[lo:lo + max(n, m)])
    return np.array(full[m - 1:n])

