# numpy.linalg in pure Python (small dense matrices), shared by both interpreters
import math
import numpy as np

_range = range


class LinAlgError(Exception):
    pass


def _mat(a):
    a = np.asarray(a)
    if a.ndim == 1:
        return [[float(v)] for v in a.tolist()]
    return [[float(v) for v in row] for row in a.tolist()]


def _vec(a):
