def _eye(n):
    return [[1.0 if i == j else 0.0 for j in _range(n)] for i in _range(n)]


def _matmul(a, b):
    n = len(a)
    m = len(b[0])
    k = len(b)
    out = []
    for i in _range(n):
        row = []
        ai = a[i]
        for j in _range(m):
            s = 0.0
            for t in _range(k):
                s += ai[t] * b[t][j]
            row.append(s)
        out.append(row)
    return out


