    return [list(r) for r in zip(*a)]


def _lu(a):
    """partial pivoting LU: returns (lu, perm, sign) or None when singular"""
    n = len(a)
    lu = [row[:] for row in a]
    perm = list(_range(n))
    sign = 1.0
    for k in _range(n):
        p = k
        big = abs(lu[k][k])
        for i in _range(k + 1, n):
            if abs(lu[i][k]) > big:
                big = abs(lu[i][k])
                p = i
        if big == 0.0:
            return None, perm, 0.0
        if p != k:
            lu[k], lu[p] = lu[p], lu[k]
            perm[k], perm[p] = perm[p], perm[k]
            sign = -sign
        piv = lu[k][k]
        for i in _range(k + 1, n):
            f = lu[i][k] / piv
            lu[i][k] = f
            if f != 0.0:
                for j in _range(k + 1, n):
                    lu[i][j] -= f * lu[k][j]
    return lu, perm, sign


