def _lu_solve(lu, perm, b):
    """solve for the columns of b (list of rows)"""
    n = len(lu)
    m = len(b[0])
    x = [b[perm[i]][:] for i in _range(n)]
    for i in _range(n):
        for k in _range(i):
            f = lu[i][k]
            if f != 0.0:
                for j in _range(m):
                    x[i][j] -= f * x[k][j]
    for i in _range(n - 1, -1, -1):
        for k in _range(i + 1, n):
            f = lu[i][k]
            if f != 0.0:
                for j in _range(m):
                    x[i][j] -= f * x[k][j]
        piv = lu[i][i]
        for j in _range(m):
            x[i][j] /= piv
