    bb = np.asarray(b)
    lu, perm, sign = _lu(m)
    if lu is None:
        raise LinAlgError("Singular matrix")
    if bb.ndim == 1:
        x = _lu_solve(lu, perm, _mat(bb))
        return np.array([r[0] for r in x])
    return np.array(_lu_solve(lu, perm, _mat(bb)))


