    return np.array(_lu_solve(lu, perm, _eye(len(m))))


def matrix_power(a, n):
    a = np.asarray(a)
    if n < 0:
        a = inv(a)
        n = -n
    result = np.eye(a.shape[0])
    if str(a.dtype).startswith('int'):
        result = result.astype(int)
    base = a
    while n > 0:
        if n % 2 == 1:
            result = result @ base
        base = base @ base
        n //= 2
    return result


def cholesky(a):
    m = _square(a)
    n = len(m)
    L = [[0.0] * n for _ in _range(n)]
    for i in _range(n):
