def _jacobi(m):
    """symmetric eigenproblem: (eigenvalues ascending, eigenvector columns)"""
    n = len(m)
    a = [row[:] for row in m]
    v = _eye(n)
    for sweep in _range(100):
        off = 0.0
        for i in _range(n):
            for j in _range(i + 1, n):
                off += a[i][j] * a[i][j]
        if off < 1e-30:
            break
        for p in _range(n - 1):
            for q in _range(p + 1, n):
                if abs(a[p][q]) < 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * a[p][q])
                if theta >= 0:
                    t = 1.0 / (theta + math.sqrt(1.0 + theta * theta))
                else:
                    t = -1.0 / (-theta + math.sqrt(1.0 + theta * theta))
                c = 1.0 / math.sqrt(1.0 + t * t)
                s = t * c
                for k in _range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in _range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in _range(n):
                    vkp = v[k][p]
                    vkq = v[k][q]
                    v[k][p] = c * vkp - s * vkq
                    v[k][q] = s * vkp + c * vkq
    vals = [a[i][i] for i in _range(n)]
    order = sorted(_range(n), key=lambda i: vals[i])
    w = [vals[i] for i in order]
    vec = [[v[r][i] for i in order] for r in _range(n)]
    return w, vec


def eigh(a, UPLO='L'):
    m = _square(a)
    n = len(m)
    sym = [[m[i][j] if (i >= j) == (UPLO == 'L') or i == j else m[j][i] for j in _range(n)] for i in _range(n)]
    w, vec = _jacobi(sym)
    return np.array(w), np.array(vec)


def eigvalsh(a, UPLO='L'):
    return eigh(a, UPLO)[0]


def _qr_eigs(m):
    """eigenvalues of a general real matrix by shifted QR iteration (real parts for complex pairs)"""
    n = len(m)
    a = [row[:] for row in m]
    eigs = []
    hi = n
    it = 0
    while hi > 0:
        if hi == 1:
            eigs.append(a[0][0])
            break
        # look for a negligible sub-diagonal element
        l = hi - 1
        while l > 0:
            if abs(a[l][l - 1]) < 1e-14 * (abs(a[l][l]) + abs(a[l - 1][l - 1]) + 1e-300):
                break
            l -= 1
        if l == hi - 1:
            eigs.append(a[hi - 1][hi - 1])
            hi -= 1
            a = [row[:hi] for row in a[:hi]]
            it = 0
            continue
        if l == hi - 2:
            p = a[hi - 2][hi - 2]
            q = a[hi - 2][hi - 1]
            r = a[hi - 1][hi - 2]
            s = a[hi - 1][hi - 1]
            tr = p + s
            dt = p * s - q * r
            disc = tr * tr / 4.0 - dt
            if disc >= 0:
                sq = math.sqrt(disc)
                eigs.append(tr / 2.0 + sq)
                eigs.append(tr / 2.0 - sq)
            else:
                eigs.append(tr / 2.0)
                eigs.append(tr / 2.0)
            hi -= 2
            a = [row[:hi] for row in a[:hi]]
            it = 0
            continue
        it += 1
        if it > 500:
            for i in _range(hi):
                eigs.append(a[i][i])
            break
        mu = a[hi - 1][hi - 1]
        if it % 11 == 10:
            mu += abs(a[hi - 1][hi - 2])
        for i in _range(hi):
            a[i][i] -= mu
        q, r = _qr_house(a, hi, hi)
        a = _matmul(r, q)
        for i in _range(hi):
            a[i][i] += mu
    return eigs


def eigvals(a):
    m = _square(a)
    n = len(m)
    sym = True
    for i in _range(n):
        for j in _range(i):
            if abs(m[i][j] - m[j][i]) > 1e-12 * (abs(m[i][j]) + abs(m[j][i]) + 1e-300):
                sym = False
