        return eigh(a)[0]
    return np.array(sorted(_qr_eigs(m)))


def eig(a):
    m = _square(a)
    n = len(m)
    sym = True
    for i in _range(n):
        for j in _range(i):
            if abs(m[i][j] - m[j][i]) > 1e-12 * (abs(m[i][j]) + abs(m[j][i]) + 1e-300):
                sym = False
    if sym:
        return eigh(a)
    w = sorted(_qr_eigs(m))
    cols = []
    for lam in w:
        shifted = [row[:] for row in m]
        for i in _range(n):
            shifted[i][i] -= lam + 1e-10 * (1.0 + abs(lam))
        lu, perm, sign = _lu(shifted)
        if lu is None:
            vec = [1.0] + [0.0] * (n - 1)
        else:
            x = [[1.0] for _ in _range(n)]
            for _ in _range(3):
                x = _lu_solve(lu, perm, x)
                nr = math.sqrt(sum(r[0] * r[0] for r in x))
                x = [[r[0] / nr] for r in x]
            vec = [r[0] for r in x]
        cols.append(vec)
    return np.array(w), np.array(_transpose(cols))


def _qr_house(a, m, n):
    """Householder QR of the m x n list matrix a: returns (Q m x m, R m x n)"""
    r = [row[:] for row in a]
    q = _eye(m)
    for k in _range(min(m - 1, n)):
        nrm = 0.0
        for i in _range(k, m):
            nrm += r[i][k] * r[i][k]
        nrm = math.sqrt(nrm)
        if nrm == 0.0:
            continue
        alpha = -nrm if r[k][k] >= 0 else nrm
        v = [0.0] * m
        for i in _range(k, m):
            v[i] = r[i][k]
        v[k] -= alpha
        vn = 0.0
        for i in _range(k, m):
            vn += v[i] * v[i]
        if vn == 0.0:
            continue
        for j in _range(n):
            s = 0.0
            for i in _range(k, m):
                s += v[i] * r[i][j]
            s = 2.0 * s / vn
            for i in _range(k, m):
                r[i][j] -= s * v[i]
        for j in _range(m):
            s = 0.0
            for i in _range(k, m):
                s += v[i] * q[j][i]
            s = 2.0 * s / vn
            for i in _range(k, m):
                q[j][i] -= s * v[i]
    for i in _range(m):
        for j in _range(min(i, n)):
            r[i][j] = 0.0
    return q, r


def qr(a, mode='reduced'):
