        return np.array(q), np.array(r)
    if mode == 'r':
        return np.array(r[:k])
    return np.array([row[:k] for row in q]), np.array(r[:k])


def _svd_core(rows, m, n):
    """one-sided Jacobi on an m x n matrix with m >= n: (U m x n, s, V n x n)"""
    u = [row[:] for row in rows]
    v = _eye(n)
    for sweep in _range(60):
        rotated = False
        for p in _range(n - 1):
            for q in _range(p + 1, n):
                alpha = 0.0
                beta = 0.0
                gamma = 0.0
                for i in _range(m):
                    alpha += u[i][p] * u[i][p]
                    beta += u[i][q] * u[i][q]
                    gamma += u[i][p] * u[i][q]
                if gamma == 0.0 or abs(gamma) <= 1e-15 * math.sqrt(alpha * beta):
                    continue
                rotated = True
                zeta = (beta - alpha) / (2.0 * gamma)
                if zeta >= 0:
                    t = 1.0 / (zeta + math.sqrt(1.0 + zeta * zeta))
                else:
                    t = -1.0 / (-zeta + math.sqrt(1.0 + zeta * zeta))
                c = 1.0 / math.sqrt(1.0 + t * t)
                s = c * t
                for i in _range(m):
                    up = u[i][p]
                    uq = u[i][q]
                    u[i][p] = c * up - s * uq
                    u[i][q] = s * up + c * uq
                for i in _range(n):
                    vp = v[i][p]
                    vq = v[i][q]
                    v[i][p] = c * vp - s * vq
                    v[i][q] = s * vp + c * vq
        if not rotated:
            break
