# private helpers shared by the scipy submodules (flat float lists, element wise mapping)
import math
import numpy as np

inf = float("inf")
nan = float("nan")


def isarr(x):
    return isinstance(x, np.ndarray)


def tolist(x):
    """flat python list of floats from a scalar / list / tuple / ndarray"""
    if isinstance(x, np.ndarray):
        if x.ndim == 0:
            return [float(x.tolist())]
        return [float(v) for v in x.flatten().tolist()]
    if isinstance(x, (list, tuple)):
        out = []
        for v in x:
            if isinstance(v, (list, tuple, np.ndarray)):
                out.extend(tolist(v))
            else:
                out.append(float(v))
        return out
    return [float(x)]


def vmap(f, x):
    """apply the scalar function f element wise; scalars give scalars, arrays arrays"""
    if isinstance(x, np.ndarray):
        if x.ndim == 0:
            return f(x.tolist())
        return np.array([f(v) for v in x.flatten().tolist()]).reshape(x.shape)
    if isinstance(x, (list, tuple)):
        return vmap(f, np.array(x))
    return f(x)


def vmap2(f, a, b):
    """element wise f(a, b) with broadcasting"""
    sa = isinstance(a, (np.ndarray, list, tuple))
    sb = isinstance(b, (np.ndarray, list, tuple))
    if not sa and not sb:
        return f(a, b)
    if not sa:
        return vmap(lambda v: f(a, v), b)
    if not sb:
        return vmap(lambda v: f(v, b), a)
    a = np.asarray(a)
    b = np.asarray(b)
    if a.shape != b.shape:
        z = (a + b) * 0
        a = a + z
        b = b + z
    fa = a.flatten().tolist()
    fb = b.flatten().tolist()
    return np.array([f(p, q) for p, q in zip(fa, fb)]).reshape(a.shape)


def vmap3(f, a, b, c):
    if not isinstance(a, (np.ndarray, list, tuple)) and not isinstance(b, (np.ndarray, list, tuple)) \
            and not isinstance(c, (np.ndarray, list, tuple)):
        return f(a, b, c)
    a = np.asarray(a)
    b = np.asarray(b)
    c = np.asarray(c)
    z = (a + b + c) * 0
    a = a + z
    b = b + z
    c = c + z
    return np.array([f(p, q, r) for p, q, r in zip(a.flatten().tolist(), b.flatten().tolist(),
                                                     c.flatten().tolist())]).reshape(a.shape)


def slices(a, axis):
    """list of 1-d lists along `axis` of a (1-d or 2-d array-like) -> (lists, kind)"""
    a = np.asarray(a)
    if a.ndim <= 1:
        return [tolist(a)], 1
    if a.ndim == 2:
        if axis < 0:
            axis += 2
        rows = [[float(v) for v in r] for r in a.tolist()]
        if axis == 1:
            return rows, 2
        n = len(rows[0]) if rows else 0
        return [[rows[i][j] for i in range(len(rows))] for j in range(n)], 2
    raise ValueError("only 1-d and 2-d inputs are supported")


def reduce_axis(f, a, axis=0):
    """f(list) -> scalar applied along axis; axis None flattens"""
    if axis is None:
        return f(tolist(a))
    sl, k = slices(a, axis)
    if k == 1:
        return f(sl[0])
    return np.array([f(s) for s in sl])


def map_axis(f, a, axis=0):
    """f(list) -> list of the same length applied along axis; keeps the shape"""
    a = np.asarray(a)
    if axis is None:
        return np.array(f(tolist(a))).reshape(a.shape)
    sl, k = slices(a, axis)
    if k == 1:
        return np.array(f(sl[0]))
    res = [f(s) for s in sl]
    if axis < 0:
        axis += 2
    if axis == 1:
        return np.array(res)
    n = len(res[0]) if res else 0
    return np.array([[res[j][i] for j in range(len(res))] for i in range(n)])


class Result:
    """tuple-like result object with named fields (NamedTuple replacement)"""

    def __init__(self, names, values, extra=None, name="Result"):
        self._names = list(names)
        self._values = list(values)
        self._rname = name
        i = 0
        for n in names:
            setattr(self, n, values[i])
            i += 1
        if extra:
            for k in extra:
                setattr(self, k, extra[k])

    def __iter__(self):
        return iter(self._values)

    def __len__(self):
        return len(self._values)

    def __getitem__(self, i):
        return self._values[i]

    def _asdict(self):
        d = {}
        i = 0
        for n in self._names:
            d[n] = self._values[i]
            i += 1
        return d

    def __repr__(self):
        s = []
        i = 0
        for n in self._names:
            s.append(n + "=" + repr(self._values[i]))
            i += 1
        return self._rname + "(" + ", ".join(s) + ")"

    def __eq__(self, other):
        if isinstance(other, Result):
            return self._values == other._values
        return tuple(self._values) == other

scipy/interpolate.py:
"""scipy.interpolate subset: interp1d (linear nearest previous next zero slinear cubic), CubicSpline, PPoly,
PchipInterpolator, CubicHermiteSpline, InterpolatedUnivariateSpline / UnivariateSpline (interpolating), lagrange,
BarycentricInterpolator, RegularGridInterpolator (linear / nearest)."""
import math
import numpy as np
from ._util import inf, nan, tolist
from . import _la


def _bisect_right(a, v):
    lo = 0
    hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if v < a[mid]:
            hi = mid
        else:
            lo = mid + 1
    return lo


def _bisect_left(a, v):
    lo = 0
    hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < v:
            lo = mid + 1
        else:
            hi = mid
    return lo


def _shape_out(vals, like):
    """vals: list of results for the flat inputs; like: original input"""
    if isinstance(like, (list, tuple, np.ndarray)):
        a = np.asarray(like)
        if a.ndim == 0:
            return vals[0]
        return np.array(vals).reshape(a.shape)
    return vals[0]


def _is_scalar(x):
    return not isinstance(x, (list, tuple, np.ndarray)) or (isinstance(x, np.ndarray) and x.ndim == 0)


# ---------------------------------------------------------------------------
# piecewise polynomials
# ---------------------------------------------------------------------------

def _poly_real_roots(co):
    """real roots of sum co[j] t**(k-1-j) (degree <= 3), sorted"""
    co = list(co)
    while len(co) > 1 and co[0] == 0.0:
        co = co[1:]
    deg = len(co) - 1
    if deg <= 0:
        return []
    if deg == 1:
        return [-co[1] / co[0]]
    if deg == 2:
        a, b, c = co
        disc = b * b - 4.0 * a * c
        if disc < 0:
            return []
        sq = math.sqrt(disc)
        q = -0.5 * (b + (sq if b >= 0 else -sq))
        r = []
        if q != 0.0:
            r.append(q / a)
            r.append(c / q)
        else:
            r.append(0.0)
        return sorted(set(r))
    if deg > 3:
        raise NotImplementedError("roots of piecewise polynomials of degree > 3")
    a, b, c, d = co
    b /= a
    c /= a
    d /= a
    q = (b * b - 3.0 * c) / 9.0
    r = (2.0 * b ** 3 - 9.0 * b * c + 27.0 * d) / 54.0
    rts = []
    q3 = q * q * q
    if r * r < q3:
        th = math.acos(max(-1.0, min(1.0, r / math.sqrt(q3))))
        sq = -2.0 * math.sqrt(q)
        rts = [sq * math.cos(th / 3.0) - b / 3.0, sq * math.cos((th + 2.0 * math.pi) / 3.0) - b / 3.0,
               sq * math.cos((th - 2.0 * math.pi) / 3.0) - b / 3.0]
    else:
        aa = -(1.0 if r >= 0 else -1.0) * (abs(r) + math.sqrt(r * r - q3)) ** (1.0 / 3.0)
        bb = q / aa if aa != 0.0 else 0.0
        rts = [aa + bb - b / 3.0]
    out = []
    for x in rts:
        for it in range(3):
            f = ((x + b) * x + c) * x + d
            fp = (3.0 * x + 2.0 * b) * x + c
            if fp == 0.0:
                break
            x = x - f / fp
        out.append(x)
    out.sort()
    ded = []
    for x in out:
        if not ded or abs(ded[-1] - x) > 1e-12 * max(1.0, abs(x)):
            ded.append(x)
    return ded


class PPoly:
    """piecewise polynomial; c[j][i] is the coefficient of (x - x_i)**(k-1-j) on [x_i, x_{i+1}]"""

    def __init__(self, c, x, extrapolate=None, axis=0):
        self.c = np.array(c) if not isinstance(c, np.ndarray) else c
        self.x = np.array(x) if not isinstance(x, np.ndarray) else x
        self._c = [[float(v) for v in r] for r in self.c.tolist()]
        self._x = tolist(self.x)
        self.extrapolate = True if extrapolate is None else extrapolate

    def _eval1(self, xv, nu, extrapolate):
        xs = self._x
        n = len(xs)
        if xv != xv:
            return nan
        if extrapolate is False or extrapolate is None and not self.extrapolate:
            if xv < xs[0] or xv > xs[-1]:
                return nan
        if extrapolate == "periodic":
            period = xs[-1] - xs[0]
            xv = xs[0] + (xv - xs[0]) % period
        i = _bisect_right(xs, xv) - 1
        if i < 0:
            i = 0
        if i > n - 2:
            i = n - 2
        c = self._c
        k = len(c)
        dx = xv - xs[i]
        if nu == 0:
            res = 0.0
            for j in range(k):
                res = res * dx + c[j][i]
            return res
        # derivative of order nu
        res = 0.0
        for j in range(k - nu):
            m = k - 1 - j
            fac = 1.0
            for q in range(nu):
                fac *= (m - q)
            res = res * dx + fac * c[j][i]
        return res

    def __call__(self, x, nu=0, extrapolate=None):
        if _is_scalar(x):
            return self._eval1(float(x), nu, extrapolate)
        xl = tolist(x)
        return _shape_out([self._eval1(v, nu, extrapolate) for v in xl], x)

    def derivative(self, nu=1):
        c = self._c
        k = len(c)
        cols = len(c[0])
        for step in range(nu):
            k = len(c)
            if k == 1:
                c = [[0.0] * cols]
            else:
                c = [[c[j][i] * (k - 1 - j) for i in range(cols)] for j in range(k - 1)]
        return PPoly(c, self._x, self.extrapolate)

    def antiderivative(self, nu=1):
        c = self._c
        xs = self._x
        cols = len(c[0])
        for step in range(nu):
            k = len(c)
            new = [[c[j][i] / (k - j) for i in range(cols)] for j in range(k)] + [[0.0] * cols]
            # make continuous
            acc = 0.0
            kk = k + 1
            for i in range(cols):
                new[kk - 1][i] = acc
                h = xs[i + 1] - xs[i]
                v = 0.0
                for j in range(kk):
                    v = v * h + new[j][i]
                acc = v
            c = new
        return PPoly(c, xs, self.extrapolate)

    def integrate(self, a, b, extrapolate=None):
        anti = self.antiderivative()
        return anti(b, extrapolate=True) - anti(a, extrapolate=True)

    def roots(self, discontinuity=True, extrapolate=None):
        xs = self._x
        ex = self.extrapolate if extrapolate is None else extrapolate
        out = []
        k = len(self._c)
        m = len(xs) - 1
        for i in range(m):
            co = [self._c[j][i] for j in range(k)]
            lo = xs[i]
            hi = xs[i + 1]
            if ex is True:
                if i == 0:
                    lo = -inf
                if i == m - 1:
                    hi = inf
            rts = _poly_real_roots(co)
            for r in rts:
                t = xs[i] + r
                if t >= lo and (t < hi or (i == m - 1 and t <= hi)):
                    if not out or abs(out[-1] - t) > 1e-13 * max(1.0, abs(t)):
                        out.append(t)
        out.sort()
        return np.array(out)

    def solve(self, y=0.0, discontinuity=True, extrapolate=None):
        if y == 0.0:
            return self.roots()
        c = [list(r) for r in self._c]
        c[-1] = [v - y for v in c[-1]]
        return PPoly(c, self._x, self.extrapolate).roots()


def _hermite_coeffs(xs, ys, ss):
    n = len(xs)
    c0 = []
    c1 = []
    c2 = []
    c3 = []
    for i in range(n - 1):
        dx = xs[i + 1] - xs[i]
        slope = (ys[i + 1] - ys[i]) / dx
        t = (ss[i] + ss[i + 1] - 2.0 * slope) / dx
        c0.append(t / dx)
        c1.append((slope - ss[i]) / dx - t)
        c2.append(ss[i])
        c3.append(ys[i])
    return [c0, c1, c2, c3]


def _solve_gtsv(dl, d, du, b):
    """tridiagonal solve with partial pivoting (LAPACK dgtsv); modifies copies"""
    n = len(d)
    dl = list(dl)
    d = list(d)
    du = list(du) + [0.0]
    b = list(b)
    for i in range(n - 1):
        if abs(d[i]) >= abs(dl[i]):
            if d[i] == 0.0:
                raise ValueError("singular matrix")
            fact = dl[i] / d[i]
            d[i + 1] = d[i + 1] - fact * du[i]
            b[i + 1] = b[i + 1] - fact * b[i]
            dl[i] = 0.0
        else:
            fact = d[i] / dl[i]
            d[i] = dl[i]
            temp = d[i + 1]
            d[i + 1] = du[i] - fact * temp
            if i < n - 2:
                dl[i] = du[i + 1]
                du[i + 1] = -fact * dl[i]
            du[i] = temp
            temp = b[i]
            b[i] = b[i + 1]
            b[i + 1] = temp - fact * b[i + 1]
    if d[n - 1] == 0.0:
        raise ValueError("singular matrix")
    b[n - 1] = b[n - 1] / d[n - 1]
    if n > 1:
        b[n - 2] = (b[n - 2] - du[n - 2] * b[n - 1]) / d[n - 2]
    for i in range(n - 3, -1, -1):
        b[i] = (b[i] - du[i] * b[i + 1] - dl[i] * b[i + 2]) / d[i]
    return b


def _spline_slopes(xs, ys, bc):
    n = len(xs)
    dx = [xs[i + 1] - xs[i] for i in range(n - 1)]
    slope = [(ys[i + 1] - ys[i]) / dx[i] for i in range(n - 1)]
    if n == 2:
        if bc[0] in ("not-a-knot",) and bc[1] in ("not-a-knot",):
            return [slope[0], slope[0]]
        if bc[0] == "periodic":
            return [0.0, 0.0]
    if bc[0] == "periodic":
        # cyclic system for n-1 unknowns
        m = n - 1
        A = [[0.0] * m for r in range(m)]
        rhs = [0.0] * m
        for i in range(m):
            im = (i - 1) % m
            ip = (i + 1) % m
            dxl = dx[im]
            dxr = dx[i]
            A[i][im] += dxr
            A[i][i] += 2.0 * (dxl + dxr)
            A[i][ip] += dxl
            rhs[i] = 3.0 * (dxr * slope[im] + dxl * slope[i])
        s = _la.solve(A, rhs)
        return s + [s[0]]
    nn = n
    if nn == 3 and bc[0] == "not-a-knot" and bc[1] == "not-a-knot":
        m0 = slope[0]
        a = (slope[1] - slope[0]) / (xs[2] - xs[0])
        return [m0 - a * dx[0], m0 + a * dx[0], m0 + a * (dx[0] + 2.0 * dx[1])]
    dl = [0.0] * (n - 1)
    d = [0.0] * n
    du = [0.0] * (n - 1)
    b = [0.0] * n
    for i in range(1, n - 1):
        dl[i - 1] = dx[i]
        d[i] = 2.0 * (dx[i - 1] + dx[i])
        du[i] = dx[i - 1]
        b[i] = 3.0 * (dx[i] * slope[i - 1] + dx[i - 1] * slope[i])
    left = bc[0]
    right = bc[1]
    if left == "not-a-knot":
        dd = xs[2] - xs[0]
        d[0] = dx[1]
        du[0] = dd
        b[0] = ((dx[0] + 2.0 * dd) * dx[1] * slope[0] + dx[0] * dx[0] * slope[1]) / dd
    elif left == "natural":
        d[0] = 2.0
        du[0] = 1.0
        b[0] = 3.0 * slope[0]
    elif left[0] == 1:
        d[0] = 1.0
        du[0] = 0.0
        b[0] = left[1]
    else:
        d[0] = 2.0
        du[0] = 1.0
        b[0] = 3.0 * slope[0] - 0.5 * dx[0] * left[1]
    if right == "not-a-knot":
        dd = xs[n - 1] - xs[n - 3]
        d[n - 1] = dx[n - 3]
        dl[n - 2] = dd
        b[n - 1] = (dx[n - 2] * dx[n - 2] * slope[n - 3] + (2.0 * dd + dx[n - 2]) * dx[n - 3] * slope[n - 2]) / dd
    elif right == "natural":
        d[n - 1] = 2.0
        dl[n - 2] = 1.0
        b[n - 1] = 3.0 * slope[n - 2]
    elif right[0] == 1:
        d[n - 1] = 1.0
        dl[n - 2] = 0.0
        b[n - 1] = right[1]
    else:
        d[n - 1] = 2.0
        dl[n - 2] = 1.0
        b[n - 1] = 3.0 * slope[n - 2] + 0.5 * dx[n - 2] * right[1]
    return _solve_gtsv(dl, d, du, b)


def _norm_bc(bc_type):
    def one(b, side):
        if isinstance(b, str):
            if b == "clamped":
                return (1, 0.0)
            if b in ("natural", "not-a-knot", "periodic"):
                return b
            raise ValueError("bc_type is not valid")
        o, v = b
        return (int(o), float(v))
    if isinstance(bc_type, str):
        if bc_type == "periodic":
            return ("periodic", "periodic")
        return (one(bc_type, 0), one(bc_type, 1))
    return (one(bc_type[0], 0), one(bc_type[1], 1))


class CubicSpline(PPoly):
    def __init__(self, x, y, axis=0, bc_type="not-a-knot", extrapolate=None):
        xs = tolist(x)
        ya = np.asarray(y)
        self._cols = None
        if ya.ndim == 2:
            cols = [CubicSpline(xs, [row[j] for row in ya.tolist()], 0, bc_type, extrapolate) for j in range(ya.shape[1])]
            self._cols = cols
            self.x = np.array(xs)
            self._x = xs
            self.extrapolate = True if extrapolate is None else extrapolate
            self._c = cols[0]._c
            self.c = cols[0].c
            return
        ys = tolist(ya)
        n = len(xs)
        if n < 2:
            raise ValueError("`x` must contain at least 2 elements.")
        for i in range(n - 1):
            if not xs[i + 1] > xs[i]:
                raise ValueError("`x` must be strictly increasing sequence.")
        bc = _norm_bc(bc_type)
        if bc[0] == "periodic" and abs(ys[0] - ys[-1]) > 1e-14 * max(1.0, abs(ys[0])):
            raise ValueError("The first and last `y` point along axis 0 must be identical (within machine precision) "
                             "when bc_type='periodic'.")
        if n == 3 and bc[0] == "not-a-knot" and bc[1] == "not-a-knot":
            m0 = (ys[1] - ys[0]) / (xs[1] - xs[0])
            aq = ((ys[2] - ys[1]) / (xs[2] - xs[1]) - m0) / (xs[2] - xs[0])
            dx0 = xs[1] - xs[0]
            coef = [[0.0, 0.0], [aq, aq], [m0 - aq * dx0, m0 + aq * dx0], [ys[0], ys[1]]]
        else:
            s = _spline_slopes(xs, ys, bc)
            coef = _hermite_coeffs(xs, ys, s)
        PPoly.__init__(self, coef, xs, extrapolate if extrapolate != "periodic" else "periodic")
        if bc[0] == "periodic" and extrapolate is None:
            self.extrapolate = "periodic"

    def __call__(self, x, nu=0, extrapolate=None):
        if self._cols is not None:
            outs = [c(x, nu, extrapolate) for c in self._cols]
            if _is_scalar(x):
                return np.array(outs)
            a = np.array([tolist(o) for o in outs])
            return a.T
        ex = extrapolate
        if ex is None:
            ex = self.extrapolate
        return PPoly.__call__(self, x, nu, ex if ex != True else None)

    def derivative(self, nu=1):
        if self._cols is not None:
            raise NotImplementedError("derivative of a vector valued spline")
        r = PPoly.derivative(self, nu)
        return r

    def integrate(self, a, b, extrapolate=None):
        sign = 1.0
        if a > b:
            a, b = b, a
            sign = -1.0
        anti = self.antiderivative()
        ex = self.extrapolate if extrapolate is None else extrapolate
        if ex == "periodic":
            xs = self._x
            period = xs[-1] - xs[0]
            full = anti(xs[-1], extrapolate=True) - anti(xs[0], extrapolate=True)
            k = math.floor((b - a) / period)
            tot = k * full
            a2 = xs[0] + (a - xs[0]) % period
            b2 = a2 + (b - a) - k * period
            if b2 <= xs[-1]:
                tot += anti(b2, extrapolate=True) - anti(a2, extrapolate=True)
            else:
                tot += anti(xs[-1], extrapolate=True) - anti(a2, extrapolate=True)
                tot += anti(xs[0] + b2 - xs[-1], extrapolate=True) - anti(xs[0], extrapolate=True)
            return sign * tot
        return sign * (anti(b, extrapolate=ex if ex else True) - anti(a, extrapolate=ex if ex else True))


class CubicHermiteSpline(PPoly):
    def __init__(self, x, y, dydx, axis=0, extrapolate=None):
        xs = tolist(x)
        PPoly.__init__(self, _hermite_coeffs(xs, tolist(y), tolist(dydx)), xs, extrapolate)


def _pchip_slopes(xs, ys):
    n = len(xs)
    hk = [xs[i + 1] - xs[i] for i in range(n - 1)]
    mk = [(ys[i + 1] - ys[i]) / hk[i] for i in range(n - 1)]
    if n == 2:
        return [mk[0], mk[0]]

    def sgn(v):
        return 1.0 if v > 0 else (-1.0 if v < 0 else 0.0)
    d = [0.0] * n
    for i in range(1, n - 1):
        m0 = mk[i - 1]
        m1 = mk[i]
        if sgn(m0) != sgn(m1) or m0 == 0 or m1 == 0:
            d[i] = 0.0
        else:
            w1 = 2.0 * hk[i] + hk[i - 1]
            w2 = hk[i] + 2.0 * hk[i - 1]
            whmean = (w1 / m0 + w2 / m1) / (w1 + w2)
            d[i] = 1.0 / whmean

    def edge(h0, h1, m0, m1):
        dd = ((2.0 * h0 + h1) * m0 - h0 * m1) / (h0 + h1)
        if sgn(dd) != sgn(m0):
            return 0.0
        if sgn(m0) != sgn(m1) and abs(dd) > 3.0 * abs(m0):
            return 3.0 * m0
        return dd
    d[0] = edge(hk[0], hk[1], mk[0], mk[1])
    d[n - 1] = edge(hk[n - 2], hk[n - 3], mk[n - 2], mk[n - 3])
    return d


class PchipInterpolator(PPoly):
    def __init__(self, x, y, axis=0, extrapolate=None):
        xs = tolist(x)
        ys = tolist(y)
        PPoly.__init__(self, _hermite_coeffs(xs, ys, _pchip_slopes(xs, ys)), xs, extrapolate)


def pchip_interpolate(xi, yi, x, der=0, axis=0):
    p = PchipInterpolator(xi, yi)
    return p(x, nu=der)


