# bracketing / scalar minimisation
# ---------------------------------------------------------------------------

def bracket(func, xa=0.0, xb=1.0, args=(), grow_limit=110.0, maxiter=1000):
    _gold = 1.618034
    _verysmall_num = 1e-21
    fa = float(func(xa, *args))
    fb = float(func(xb, *args))
    funcalls = 2
    if fa < fb:
        xa, xb = xb, xa
        fa, fb = fb, fa
    xc = xb + _gold * (xb - xa)
    fc = float(func(xc, *args))
    funcalls += 1
    it = 0
    while fc < fb:
        tmp1 = (xb - xa) * (fb - fc)
        tmp2 = (xb - xc) * (fb - fa)
        val = tmp2 - tmp1
        if abs(val) < _verysmall_num:
            denom = 2.0 * _verysmall_num
        else:
            denom = 2.0 * val
        w = xb - ((xb - xc) * tmp2 - (xb - xa) * tmp1) / denom
        wlim = xb + grow_limit * (xc - xb)
        if it > maxiter:
            raise RuntimeError("Too many iterations.")
        it += 1
        if (w - xc) * (xb - w) > 0.0:
            fw = float(func(w, *args))
            funcalls += 1
            if fw < fc:
                xa = xb
                xb = w
                fa = fb
                fb = fw
                break
            elif fw > fb:
                xc = w
                fc = fw
                break
            w = xc + _gold * (xc - xb)
            fw = float(func(w, *args))
            funcalls += 1
        elif (w - wlim) * (wlim - xc) >= 0.0:
            w = wlim
            fw = float(func(w, *args))
            funcalls += 1
        elif (w - wlim) * (xc - w) > 0.0:
            fw = float(func(w, *args))
            funcalls += 1
            if fw < fc:
                xb = xc
                xc = w
                w = xc + _gold * (xc - xb)
                fb = fc
                fc = fw
                fw = float(func(w, *args))
                funcalls += 1
        else:
            w = xc + _gold * (xc - xb)
            fw = float(func(w, *args))
            funcalls += 1
        xa = xb
        xb = xc
        xc = w
        fa = fb
        fb = fc
        fc = fw
    return xa, xb, xc, fa, fb, fc, funcalls


def _brent_core(func, args, brack, tol, maxiter):
    if brack is None:
        xa, xb, xc, fa, fb, fc, funcalls = bracket(func, args=args)
    elif len(brack) == 2:
        xa, xb, xc, fa, fb, fc, funcalls = bracket(func, xa=brack[0], xb=brack[1], args=args)
    elif len(brack) == 3:
        xa, xb, xc = brack
        if xa > xc:
            xc, xa = xa, xc
        if not ((xa < xb) and (xb < xc)):
            raise ValueError("Not a bracketing interval.")
        fa = float(func(xa, *args))
        fb = float(func(xb, *args))
        fc = float(func(xc, *args))
        if not ((fb < fa) and (fb < fc)):
            raise ValueError("Not a bracketing interval.")
        funcalls = 3
    else:
        raise ValueError("Bracketing interval must be length 2 or 3 sequence.")
    _mintol = 1.0e-11
    _cg = 0.3819660
    x = xb
    w = xb
    v = xb
    fw = fb
    fv = fb
    fx = fb
    if xa < xc:
        a = xa
        b = xc
    else:
        a = xc
        b = xa
    deltax = 0.0
    rat = 0.0
    it = 0
    while it < maxiter:
        tol1 = tol * abs(x) + _mintol
        tol2 = 2.0 * tol1
        xmid = 0.5 * (a + b)
        if abs(x - xmid) < (tol2 - 0.5 * (b - a)):
            break
        if abs(deltax) <= tol1:
            if x >= xmid:
                deltax = a - x
            else:
                deltax = b - x
            rat = _cg * deltax
        else:
            tmp1 = (x - w) * (fx - fv)
            tmp2 = (x - v) * (fx - fw)
            p = (x - v) * tmp2 - (x - w) * tmp1
            tmp2 = 2.0 * (tmp2 - tmp1)
            if tmp2 > 0.0:
                p = -p
            tmp2 = abs(tmp2)
            dx_temp = deltax
            deltax = rat
            if (p > tmp2 * (a - x)) and (p < tmp2 * (b - x)) and (abs(p) < abs(0.5 * tmp2 * dx_temp)):
                rat = p * 1.0 / tmp2
                u = x + rat
                if (u - a) < tol2 or (b - u) < tol2:
                    if xmid - x >= 0:
                        rat = tol1
                    else:
                        rat = -tol1
            else:
                if x >= xmid:
                    deltax = a - x
                else:
                    deltax = b - x
                rat = _cg * deltax
        if abs(rat) < tol1:
            if rat >= 0:
                u = x + tol1
            else:
                u = x - tol1
        else:
            u = x + rat
        fu = float(func(u, *args))
        funcalls += 1
        if fu > fx:
            if u < x:
                a = u
            else:
                b = u
            if (fu <= fw) or (w == x):
                v = w
                w = u
                fv = fw
                fw = fu
            elif (fu <= fv) or (v == x) or (v == w):
                v = u
                fv = fu
        else:
            if u >= x:
                a = x
            else:
                b = x
            v = w
            w = x
            x = u
            fv = fw
            fw = fx
            fx = fu
        it += 1
    return x, fx, it, funcalls


def brent(func, args=(), brack=None, tol=1.48e-8, full_output=0, maxiter=500):
    x, fx, it, nf = _brent_core(func, args, brack, tol, maxiter)
    if full_output:
        return x, fx, it, nf
    return x


def _fminbound_core(func, x1, x2, args, xatol, maxfun):
    sqrt_eps = math.sqrt(2.2e-16)
    golden_mean = 0.5 * (3.0 - math.sqrt(5.0))
    a = x1
    b = x2
    fulc = a + golden_mean * (b - a)
    nfc = fulc
    xf = fulc
    rat = 0.0
    e = 0.0
    x = xf
    fx = float(func(x, *args))
    num = 1
    ffulc = fx
    fnfc = fx
    xm = 0.5 * (a + b)
    tol1 = sqrt_eps * abs(xf) + xatol / 3.0
    tol2 = 2.0 * tol1
    flag = 0
    while abs(xf - xm) > (tol2 - 0.5 * (b - a)):
        golden = 1
        if abs(e) > tol1:
            golden = 0
            r = (xf - nfc) * (fx - ffulc)
            q = (xf - fulc) * (fx - fnfc)
            p = (xf - fulc) * q - (xf - nfc) * r
            q = 2.0 * (q - r)
            if q > 0.0:
                p = -p
            q = abs(q)
            r = e
            e = rat
            if (abs(p) < abs(0.5 * q * r)) and (p > q * (a - xf)) and (p < q * (b - xf)):
                rat = (p + 0.0) / q
                x = xf + rat
                if ((x - a) < tol2) or ((b - x) < tol2):
                    si = 1.0 if (xm - xf) >= 0 else -1.0
                    rat = tol1 * si
            else:
                golden = 1
        if golden:
            if xf >= xm:
                e = a - xf
            else:
                e = b - xf
            rat = golden_mean * e
        si = 1.0 if rat >= 0 else -1.0
        x = xf + si * max(abs(rat), tol1)
        fu = float(func(x, *args))
        num += 1
        if fu <= fx:
            if x >= xf:
                a = xf
            else:
                b = xf
            fulc = nfc
            ffulc = fnfc
            nfc = xf
            fnfc = fx
            xf = x
            fx = fu
        else:
            if x < xf:
                a = x
            else:
                b = x
            if (fu <= fnfc) or (nfc == xf):
                fulc = nfc
                ffulc = fnfc
                nfc = x
                fnfc = fu
            elif (fu <= ffulc) or (fulc == xf) or (fulc == nfc):
                fulc = x
                ffulc = fu
        xm = 0.5 * (a + b)
        tol1 = sqrt_eps * abs(xf) + xatol / 3.0
        tol2 = 2.0 * tol1
        if num >= maxfun:
            flag = 1
            break
    return xf, fx, flag, num


def fminbound(func, x1, x2, args=(), xtol=1e-5, maxfun=500, full_output=0, disp=1):
    xf, fx, flag, num = _fminbound_core(func, x1, x2, args, xtol, maxfun)
    if full_output:
        return xf, fx, flag, num
    return xf


def _golden_core(func, args, brack, tol, maxiter):
    _gold = 1.618034
    _grat = 2.0 - _gold
    _tol = 1.0 / (_gold ** 2) * 0 + tol
    if brack is None:
        xa, xb, xc, fa, fb, fc, funcalls = bracket(func, args=args)
    elif len(brack) == 2:
        xa, xb, xc, fa, fb, fc, funcalls = bracket(func, xa=brack[0], xb=brack[1], args=args)
    else:
        xa, xb, xc = brack
        funcalls = 0
    _gR = 0.61803399
    _gC = 1.0 - _gR
    x3 = xc
    x0 = xa
    if abs(xc - xb) > abs(xb - xa):
        x1 = xb
        x2 = xb + _gC * (xc - xb)
    else:
        x2 = xb
        x1 = xb - _gC * (xb - xa)
    f1 = float(func(x1, *args))
    f2 = float(func(x2, *args))
    funcalls += 2
    nit = 0
    for i in range(maxiter):
        if abs(x3 - x0) <= _tol * (abs(x1) + abs(x2)):
            break
        if f2 < f1:
            x0 = x1
            x1 = x2
            x2 = _gR * x1 + _gC * x3
            f1 = f2
            f2 = float(func(x2, *args))
        else:
            x3 = x2
            x2 = x1
            x1 = _gR * x2 + _gC * x0
            f2 = f1
            f1 = float(func(x1, *args))
        funcalls += 1
        nit += 1
    if f1 < f2:
        return x1, f1, nit, funcalls
    return x2, f2, nit, funcalls


def golden(func, args=(), brack=None, tol=1.4901161193847656e-08, full_output=0, maxiter=5000):
    x, fx, it, nf = _golden_core(func, args, brack, tol, maxiter)
    if full_output:
        return x, fx, nf
    return x


def minimize_scalar(fun, bracket=None, bounds=None, args=(), method=None, tol=None, options=None):
    if options is None:
        options = {}
    if method is None:
        method = "brent" if bounds is None else "bounded"
    m = method.lower()
    if m == "bounded":
        if bounds is None or len(bounds) != 2:
            raise ValueError("The `bounds` parameter is mandatory for method `bounded`.")
        xatol = options.get("xatol", 1e-5 if tol is None else tol)
        x, fx, flag, num = _fminbound_core(fun, bounds[0], bounds[1], args, xatol, options.get("maxiter", 500))
        msg = "Solution found." if flag == 0 else "Maximum number of function calls reached."
        return OptimizeResult(fun=fx, x=x, nit=num, nfev=num, success=(flag == 0), message=msg, status=flag)
    xtol = options.get("xtol", 1.48e-8 if tol is None else tol)
    if m == "golden":
        xtol = options.get("xtol", 1.4901161193847656e-08 if tol is None else tol)
        x, fx, it, nf = _golden_core(fun, args, bracket, xtol, options.get("maxiter", 5000))
        return OptimizeResult(fun=fx, x=x, nit=it, nfev=nf, success=True)
    if m != "brent":
        raise ValueError("Unknown solver " + method)
    x, fx, it, nf = _brent_core(fun, args, bracket, xtol, options.get("maxiter", 500))
    return OptimizeResult(fun=fx, x=x, nit=it, nfev=nf, success=(it < options.get("maxiter", 500)))


