import numpy as np

nan = float('nan')


class NAType:
    def __repr__(self):
        return '<NA>'

    def __bool__(self):
        raise TypeError('boolean value of NA is ambiguous')

    def __eq__(self, other):
        return self

    def __ne__(self, other):
        return self

    def __hash__(self):
        return 12345


NA = NAType()


