class Dtype:
    def __init__(self, name):
        self.name = name

    @property
    def kind(self):
        n = self.name
        if n == 'int64':
            return 'i'
        if n == 'float64':
            return 'f'
        if n == 'bool':
            return 'b'
        if n.startswith('datetime'):
            return 'M'
        return 'O'

    def __str__(self):
        return self.name

    def __repr__(self):
        if self.name == 'str':
            return "<StringDtype(storage='python', na_value=nan)>"
        if self.name == 'object':
            return "dtype('O')"
        return "dtype('%s')" % self.name

    def __eq__(self, other):
        if isinstance(other, Dtype):
            return other.name == self.name
        if isinstance(other, str):
            if other == self.name:
                return True
            if other in ('O', 'object'):
                return self.name == 'object'
            if other in ('int', 'i8', 'int64'):
                return self.name == 'int64'
            if other in ('float', 'f8', 'float64', 'double'):
                return self.name == 'float64'
            if other in ('string', 'str'):
                return self.name == 'str'
            return False
        if other is int:
            return self.name == 'int64'
        if other is float:
            return self.name == 'float64'
        if other is bool:
            return self.name == 'bool'
        if other is str:
            return self.name == 'str'
        if other is object:
            return self.name == 'object'
        nm = getattr(other, '__name__', None)
        if nm is not None:
            return nm == self.name or (nm == 'float' and self.name == 'float64')
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash(self.name)


_dts = {}


def dtype_of(name):
    d = _dts.get(name)
    if d is None:
        d = Dtype(name)
        _dts[name] = d
    return d


def norm_dtype(dt):
    """user supplied dtype -> internal name"""
    if dt is None:
        return None
    if isinstance(dt, Dtype):
        return dt.name
    if dt is int:
        return 'int64'
    if dt is float:
        return 'float64'
    if dt is bool:
        return 'bool'
    if dt is str:
        return 'str'
    if dt is object:
        return 'object'
    if isinstance(dt, str):
        d = dt.lower()
        if d.startswith('int') or d.startswith('uint'):
            return 'int64'
        if d.startswith('float') or d == 'double':
            return 'float64'
        if d in ('bool', 'boolean'):
            return 'bool'
        if d in ('str', 'string', 'unicode'):
            return 'str'
        if d in ('object', 'o'):
            return 'object'
        if d.startswith('datetime64'):
            return 'datetime64[us]'
        if d == 'category':
            return 'object'
        return dt
    nm = getattr(dt, '__name__', None)
    if nm is not None:
        return norm_dtype(nm)
    return str(dt)


def infer(vals):
    """returns (values, dtype name); values may be a converted copy"""
    if len(vals) == 0:
        return vals, 'object'
    ts = set(map(type, vals))
    has_none = False
    if type(None) in ts:
        has_none = True
        ts.discard(type(None))
    if NAType in ts:
        has_none = True
        ts.discard(NAType)
    if len(ts) == 0:
        return vals, 'object'
    if len(ts) == 1:
        t = list(ts)[0]
        if t is int and not has_none:
            return vals, 'int64'
        if t is bool and not has_none:
            return vals, 'bool'
        if t is float:
            if has_none:
                vals = [nan if (x is None or x is NA) else x for x in vals]
            return vals, 'float64'
        if t is int:
            return [nan if (x is None or x is NA) else float(x) for x in vals], 'float64'
        if t is str:
            if has_none:
                vals = [nan if (x is None or x is NA) else x for x in vals]
            return vals, 'str'
    elif len(ts) == 2 and int in ts and float in ts:
        return [nan if (x is None or x is NA) else float(x) for x in vals], 'float64'
    elif len(ts) == 2 and str in ts and float in ts:
        ok = True
        for x in vals:
            if type(x) is float and x == x:
                ok = False
                break
        if ok:
            if has_none:
                vals = [nan if (x is None or x is NA) else x for x in vals]
            return vals, 'str'
    if float in ts:
        ts2 = set(ts)
        ts2.discard(float)
        if len(ts2) == 1:
            nm = getattr(list(ts2)[0], '__name__', '')
            if nm in ('datetime', 'Timestamp', 'timedelta', 'Timedelta'):
                ok = True
                for x in vals:
                    if type(x) is float and x == x:
                        ok = False
                if ok:
                    return [nan if (x is None or x is NA) else x for x in vals], ('datetime64[us]' if nm in ('datetime', 'Timestamp') else 'timedelta64[us]')
    if len(ts) == 1:
        nm = getattr(list(ts)[0], '__name__', '')
        if nm == 'datetime' or nm == 'Timestamp':
            if has_none:
                vals = [nan if (x is None or x is NA) else x for x in vals]
            return vals, 'datetime64[us]'
        if nm == 'timedelta' or nm == 'Timedelta':
            if has_none:
                vals = [nan if (x is None or x is NA) else x for x in vals]
            return vals, 'timedelta64[us]'
    return vals, 'object'


def is_numeric_dt(dt):
    return dt == 'int64' or dt == 'float64' or dt == 'bool'


