class ObjArray:
    """stand-in for numpy object arrays (the native numpy only has int/float/bool)"""

    def __init__(self, a):
        self._a = a

    @property
    def shape(self):
        s = []
        x = self._a
        while isinstance(x, list):
            s.append(len(x))
            if len(x) == 0:
                break
            x = x[0]
        return tuple(s)

    @property
    def ndim(self):
        return len(self.shape)

    @property
    def size(self):
        n = 1
        for k in self.shape:
            n *= k
        return n

    @property
    def dtype(self):
        return dtype_of('object')

    @property
    def T(self):
        if self.ndim == 2:
            return ObjArray([list(r) for r in zip(*self._a)])
        return self

    def tolist(self):
        return [list(r) if isinstance(r, list) else r for r in self._a]

    def __len__(self):
        return len(self._a)

    def __iter__(self):
        return iter(self._a)

    def __getitem__(self, k):
        if isinstance(k, tuple):
            r = self._a[k[0]] if not isinstance(k[0], slice) else self._a[k[0]]
            if isinstance(k[0], slice):
                return ObjArray([x[k[1]] for x in r])
            return r[k[1]]
        r = self._a[k]
        if isinstance(k, slice):
            return ObjArray(r)
        return r

    def copy(self):
        return ObjArray(self.tolist())

    def astype(self, dt):
        dn = norm_dtype(dt)
        if dn == 'float64':
            return np.array(_conv_nested(self._a, float))
        if dn == 'int64':
            return np.array(_conv_nested(self._a, int))
        return self

    def flatten(self):
        if self.ndim == 2:
            return ObjArray([x for r in self._a for x in r])
        return self

    def __eq__(self, o):
        if isinstance(o, ObjArray):
            return self._a == o._a
        return np.array([x == o for x in self._a])

    def __ne__(self, o):
        r = self.__eq__(o)
        if isinstance(r, bool):
            return not r
        return ~r

    def __hash__(self):
        return id(self)

    def __repr__(self):
        if self.ndim == 2:
            return '[' + '\n '.join(['[' + ' '.join([repr(x) for x in r]) + ']' for r in self._a]) + ']'
        return '[' + ' '.join([repr(x) for x in self._a]) + ']'

    __str__ = __repr__


