    def astype(self, dtype, copy=True, errors='raise'):
        dn = norm_dtype(dtype)
        if dn == self._dt:
            return self.copy()
        if dn == 'int64' and self._dt == 'str':
            return self._new([int(x) for x in self._v], 'int64')
        return self._new(_astype_vals(self._v, self._dt, dn), dn)

