            for j in range(nr):
                m = lmap.get(rkn[j])
                if m is None:
                    lpos.append(None)
                    rpos.append(j)
                else:
                    for i in m:
                        lpos.append(i)
                        rpos.append(j)
        else:
            used = {}
            for i in range(nl):
                m = rmap.get(lkn[i])
                if m is None:
                    if how in ('left', 'outer'):
                        lpos.append(i)
                        rpos.append(None)
                else:
                    for j in m:
                        lpos.append(i)
                        rpos.append(j)
                        used[j] = 1
            if how == 'outer':
                for j in range(nr):
                    if j not in used:
                        lpos.append(None)
                        rpos.append(j)
        # sort by key
        if sort or how == 'outer':
            def kk(t):
                i, j = t
                k = lkn[i] if i is not None else rkn[j]
                return k
            pairs = list(zip(lpos, rpos))
            try:
                good = [p for p in pairs if None not in kk(p)]
                bad = [p for p in pairs if None in kk(p)]
                if how == 'outer' or sort:
                    good = sorted(good, key=kk)
                pairs = good + bad
            except Exception:
                pass
            lpos = [p[0] for p in pairs]
            rpos = [p[1] for p in pairs]
    n = len(lpos)
    lnames = list(left._cols._v)
