_SPECIAL = '.^$*+?{}[]\\|()'


def _isre(p):
    for ch in p:
        if ch in _SPECIAL:
            return True
    return False


def _re():
    import re
    return re


class StringMethods:
    def __init__(self, s):
        if s._dt not in ('str', 'object'):
            raise AttributeError('Can only use .str accessor with string values!')
        self.s = s

    def _map(self, f, dt=None):
        res = []
        for x in self.s._v:
            if isinstance(x, str):
                res.append(f(x))
            else:
                res.append(nan)
