    def _mapb(self, f, na=nan):
        if self.s._dt == 'str' and na != na:
            na = False
        res = []
        for x in self.s._v:
            if isinstance(x, str):
                res.append(f(x))
            else:
                res.append(na)
        return self.s._new(res)

